Object.assign(window.TEM8_DICTIONARY, {"flaunt":{"media":{"uk":"media/uk/flaunt__gb_1.mp3","us":"media/us/flaunt__us_1.mp3"},"oxford":{"phon":"flɔːnt","pos":"verb","senses":[{"en":"to show sth you are proud of to other people, in order to impress them","cn":"炫耀；夸示；夸耀；卖弄"},{"en":"to behave in a confident and sexual way to attract attention （","cn":"性感地）招摇过市"}]},"collins":{"senses":[{"pos":"[VERB 动词]","cn":"炫耀;夸耀;卖弄；"},{"pos":"[VERB 动词]","cn":"招摇过市;卖弄性感;搔首弄姿；"}]},"examples":[{"en":"She openly flaunted her affair with the senator.","cn":"她公开夸耀与参议员的恋情。"},{"en":"He did not believe in flaunting his wealth.","cn":"他不相信摆阔有什么好处。"}]},"flies":{"media":{"uk":"media/uk/flies__gb_1.mp3","us":"media/us/flies__us_1.mp3"},"oxford":{"phon":"flaɪz","pos":"noun","senses":[{"en":"the space above the stage in a theatre, used for lights and for storing scenery （","cn":"舞台上方）悬吊布景的空间，吊景区"}]}},"flower":{"media":{"img":["media/pic/flowerlabels_flowers_comp.jpg","media/thumb/flower.jpg"],"uk":"media/uk/flower__gb_1.mp3","us":"media/us/flower__us_1.mp3"},"oxford":{"phon":"ˈflaʊə(r)","pos":"noun","senses":[{"en":"the coloured part of a plant from which the seed or fruit develops. Flowers usually grow at the end of a stem and last only a short time.","cn":"花；花朵"},{"en":"a plant grown for the beauty of its flowers","cn":"开花植物"}]},"collins":{"senses":[{"pos":"[N-COUNT 可数名词]","cn":"花朵;鲜花；"},{"pos":"[N-COUNT 可数名词]","cn":"(已摘的)带梗的花；"}]},"examples":[{"en":"The plant has a beautiful bright red flower.","cn":"这株植物开了一朵美丽鲜红的花。"},{"en":"The roses are in flower early this year.","cn":"今年玫瑰花开得早。"}]},"flowering":{"media":{"uk":"media/uk/flowering__gb_1.mp3","us":"media/us/flowering__us_1.mp3"},"oxford":{"phon":"ˈflaʊərɪŋ","pos":"noun","senses":[{"en":"the time when a plant has flowers","cn":"开花时节"},{"en":"the time when sth, especially a period of new ideas in art, music, science, etc., reaches its most complete and successful stage of development （","cn":"艺术、音乐、科学等新思潮的）繁荣时期，鼎盛时期"}]},"collins":{"senses":[{"pos":"[N-UNCOUNT 不可数名词]","cn":"(想法或艺术风格)成熟，风行，盛行；"},{"pos":"[ADJ 形容词]","cn":"开花的;有花的；"}]},"examples":[{"en":"The 19th century saw a flowering of science and technology. 19","cn":"世纪见证了科学和技术的繁荣。"}]},"fly":{"media":{"uk":"media/uk/fly__gb_1.mp3","us":"media/us/fly__us_1.mp3"},"oxford":{"phon":"flaɪ","pos":"verb","senses":[{"en":"to move through the air, using wings","cn":"飞；飞翔"},{"en":"to move through air or space （","cn":"在空中或宇宙）飞行，航行"}]},"collins":{"senses":[{"pos":"[N-COUNT 可数名词]","cn":"苍蝇；"},{"pos":"[VERB 动词]","cn":"飞;飞行;飞翔；"}]},"examples":[{"en":"Lufthansa fly to La Paz from Frankfurt.","cn":"汉莎航空公司的飞机从法兰克福飞往拉巴斯。"},{"en":"I'd love to be a fly on the wall when he tells her the news.","cn":"他把这消息告诉她时，我想悄悄在旁观看。"}]},"flux":{"media":{"uk":"media/uk/flux__gb_1.mp3","us":"media/us/flux__us_1.mp3"},"oxford":{"phon":"flʌks","pos":"noun","senses":[{"en":"continuous movement and change","cn":"不断的变动；不停的变化"},{"en":"( technical","cn":"术语 ) a flow; an act of flowing 通量；流动"}]},"collins":{"senses":[{"pos":"[N-UNCOUNT 不可数名词]","cn":"变动;波动；"},{"pos":"[N-VAR 可变名词]","cn":"流体；"}]},"examples":[{"en":"Our society is in a state of flux.","cn":"我们的社会在不断演变。"},{"en":"a flux of neutrons","cn":"一个中子通量"}]},"floating":{"media":{"uk":"media/uk/floating__gb_1.mp3","us":"media/us/floating__us_1.mp3"},"oxford":{"phon":"ˈfləʊtɪŋ","pos":"adj.","senses":[{"en":"not fixed permanently in one particular position or place","cn":"不固定的；流动的；浮动的"}]},"examples":[{"en":"a floating population (= one in which people frequently move from one place to another)","cn":"流动人口"},{"en":"( medical","cn":"医 ) a floating kidney 游走肾"}]},"flute":{"media":{"img":["media/pic/woodwind_musicalinstruments_comp.jpg","media/thumb/flute.jpg"],"uk":"media/uk/flute__gb_1.mp3","us":"media/us/flute__us_1.mp3"},"oxford":{"phon":"fluːt","pos":"noun","senses":[{"en":"a musical instrument of the woodwind group, shaped like a thin pipe. The player holds it sideways and blows across a hole at one end.","cn":"长笛"},{"en":"a tall narrow glass used for drinking champagne","cn":"细长香槟杯（形似长笛）"}]},"collins":{"senses":[{"pos":"[N-VAR 可变名词]","cn":"长笛；"}]}},"flows":{"oxford":{"phon":"fləʊ","pos":"noun","senses":[{"en":"the steady and continuous movement of sth/sb in one direction","cn":"流；流动"},{"en":"the continuous production or supply of sth","cn":"持续生产；不断供应"}]},"collins":{"senses":[{"pos":"[VERB 动词]","cn":"流动;流向；"},{"pos":"[VERB 动词]","cn":"(人群或事物)流动，持续移动；"}]},"media":{"uk":"media/uk/flow__gb_1.mp3","us":"media/us/flow__us_1.mp3"}},"flag":{"oxford":{"phon":"flæɡ","pos":"noun","senses":[{"en":"a piece of cloth with a special coloured design on it that may be the symbol of a particular country or organization, or may have a particular meaning. A flag can be attached to a pole or held in the hand","cn":"旗"},{"en":"used to refer to a particular country or organization and its beliefs and values","cn":"旗帜（指某国家或组织及其信仰和价值观）"}]},"collins":{"senses":[{"pos":"[N-COUNT 可数名词]","cn":"旗;旗帜;(尤指)国旗；"},{"pos":"[N-COUNT 可数名词]","cn":"(在售旗募捐日出售或在某个位置上作标记用的)小旗，旗状物；"}]},"media":{"uk":"media/uk/flag__gb_1.mp3","us":"media/us/flag__us_1.mp3","img":["media/ldoce/img/flag.jpg"]},"examples":[{"en":"Our exporters keep the flag flying at international trade exhibitions.","cn":"我们的出口商在国际贸易展览会上代表我们的国家参展。"},{"en":"The report flagged up the dangers of under-age drinking.","cn":"这篇报道引起大众对未成年人饮酒危害的关注。"}]},"flying":{"media":{"uk":"media/uk/flying__gb_1.mp3","us":"media/us/flying__us_1.mp3"},"oxford":{"phon":"ˈflaɪɪŋ","pos":"adjective","senses":[{"en":"able to fly","cn":"能飞的"},{"en":"very well; with a very high mark/grade","cn":"很好；成绩优异"}]},"collins":{"senses":[{"pos":"[ADJ 形容词]","cn":"(动物)会飞的，有翼的；"},{"pos":"[PHRASE 短语]","cn":"有良好的开端;顺利开始；"}]},"examples":[{"en":"She passed the exam with flying colours.","cn":"她以优异成绩通过了考试。"},{"en":"I'm terrified of flying.","cn":"我十分害怕坐飞机。"}]},"flash":{"media":{"img":["media/pic/creativehobbies_comp.jpg","media/thumb/photography.jpg"],"uk":"media/uk/flash__gb_1.mp3","us":"media/us/flash__us_1.mp3"},"oxford":{"phon":"flæʃ","pos":"verb","senses":[{"en":"to shine very brightly for a short time; to make sth shine in this way （","cn":"使）闪耀，闪光"},{"en":"to use a light to give sb a signal","cn":"用光发出信号"}]},"collins":{"senses":[{"pos":"[N-COUNT 可数名词]","cn":"闪耀;闪光；"},{"pos":"[V-ERG 及物/不及物动词]","cn":"使闪光,使闪耀;(尤指)频闪；"}]},"examples":[{"en":"It flashed on me that he was the man I'd seen in the hotel.","cn":"我顿时认出他就是我在旅馆里看到的那个人。"},{"en":"There was a blinding flash and the whole building shuddered.","cn":"一道眩目的闪光过后，整栋大楼颤抖起来。"}]},"flu":{"oxford":{"phon":"fluː","pos":"noun","senses":[{"en":"an infectious disease like a very bad cold, that causes fever, pains and weakness","cn":"流行性感冒；流感"}]},"collins":{"senses":[{"pos":"[N-UNCOUNT 不可数名词]","cn":"流感；"}]},"media":{"uk":"media/uk/flu__gb_1.mp3","us":"media/us/flu__us_1.mp3"},"examples":[{"en":"The whole family has the flu.","cn":"全家都患流感。"},{"en":"( BrE ) She's got flu.","cn":"她患上了流感。"}]},"flimsy":{"media":{"uk":"media/uk/flimsy__gb_1.mp3","us":"media/us/flimsy__us_1.mp3"},"oxford":{"phon":"ˈflɪmzi","pos":"adj.","senses":[{"en":"badly made and not strong enough for the purpose for which it is used","cn":"劣质的；不结实的"},{"en":"thin and easily torn","cn":"薄而易损坏的"}]},"collins":{"senses":[{"pos":"[ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词]","cn":"不结实的;劣质的;不牢固的；"},{"pos":"[ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词]","cn":"(衣服或布料)薄的，不御寒的；"}]},"examples":[{"en":"The evidence against him is pretty flimsy.","cn":"对他不利的证据很难站住脚。"},{"en":"a flimsy piece of paper/fabric/plastic","cn":"薄薄的一张纸/一块织物/一片塑料"}]},"flawed":{"media":{"uk":"media/uk/flawed__gb_1.mp3","us":"media/us/flawed__us_1.mp3"},"oxford":{"phon":"flɔːd","pos":"adj.","senses":[{"en":"having a flaw; damaged or spoiled","cn":"有错误的；有缺点的；有瑕疵的"}]},"collins":{"senses":[{"pos":"[ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词]","cn":"有瑕疵的;有错误的;有缺陷的；"}]},"examples":[{"en":"seriously/fundamentally/fatally flawed","cn":"有严重/根本/致命缺点"},{"en":"the book's flawed heroine","cn":"书中有弱点的女主角"}]},"flood":{"media":{"uk":"media/uk/flood__gb_1.mp3","us":"media/us/flood__us_1.mp3"},"oxford":{"phon":"flʌd","pos":"noun","senses":[{"en":"a large amount of water covering an area that is usually dry","cn":"洪水；水灾"},{"en":"a very large number of things or people that appear at the same time","cn":"大批，大量（的人或事物）"}]},"collins":{"senses":[{"pos":"[N-VAR 可变名词]","cn":"洪水;水灾；"},{"pos":"[V-ERG 及物/不及物动词]","cn":"淹没;使充满水；"}]},"examples":[{"en":"A man who planned to flood Britain with cocaine was jailed for 15 years.","cn":"一个企图在英国大量销售可卡因的男人被判刑 15 年。"},{"en":"Police have issued flood warnings for Nevada.","cn":"警方已经发布了内华达州的水灾警告。"}]},"flooding":{"media":{"uk":"media/uk/flooding__gb_1.mp3","us":"media/us/flooding__us_1.mp3"},"collins":{"senses":[{"pos":"[N-UNCOUNT 不可数名词]","cn":"洪水泛滥;水灾；"}]},"examples":[{"en":"There will be heavy rain with flooding in some areas.","cn":"将有大雨，有些地方会泛滥成灾。"},{"en":"The heavy rain has led to serious flooding in some areas.","cn":"大雨造成部分地区发生严重水灾。"}]},"flexibility":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the ability to change or be changed easily to suit a different situation","cn":"灵活性"},{"en":"the ability to bend or be bent easily","cn":"弹性﹐柔韧性"}]},"examples":[{"en":"Employees expect flexibility in the workplace.","cn":"员工们期望能够灵活办公。","src":"ld"},{"en":"Stretching exercises will help your flexibility.","cn":"伸展运动能增强身体柔韧性。","src":"ld"}],"media":{"uk":"media/uk/flexibility__gb_1.mp3","us":"media/us/flexibility__us_1.mp3"}},"flavours":{"oxford":{"phon":"ˈfleɪvə(r)","pos":"noun","senses":[{"en":"how food or drink tastes （","cn":"食物或饮料的）味道"},{"en":"a particular type of taste （","cn":"某种）味道"}]}},"flattering":{"media":{"uk":"media/uk/flattering__gb_1.mp3","us":"media/us/flattering__us_1.mp3"},"oxford":{"phon":"ˈflætərɪŋ","pos":"adj.","senses":[{"en":"making sb look more attractive","cn":"使人显得更漂亮的"},{"en":"saying nice things about sb/sth","cn":"奉承的；阿谀的；讨好的"}]},"collins":{"senses":[{"pos":"[ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词]","cn":"使人显得更漂亮的；"},{"pos":"[ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词]","cn":"谄媚的;奉承的;讨好的；"}]},"examples":[{"en":"I found it flattering that he still recognized me after all these years.","cn":"过了这么多年他还认得我，使我觉得荣幸。"},{"en":"a flattering dress","cn":"穿上去使人更漂亮的连衣裙"}]},"flavour":{"oxford":{"phon":"ˈfleɪvə(r)","pos":"noun","senses":[{"en":"how food or drink tastes （","cn":"食物或饮料的）味道"},{"en":"a particular type of taste （","cn":"某种）味道"}]},"collins":{"senses":[{"pos":"[N-VAR 可变名词]","cn":"味;滋味;味道；"},{"pos":"[N-COUNT 可数名词]","cn":"(食物等的)口味，味道；"}]},"media":{"uk":"media/uk/flavour__gb_1.mp3","us":"media/us/flavour__us_1.mp3"},"examples":[{"en":"Foreign visitors help to give a truly international flavour to the occasion.","cn":"外国客人使这个场合显出一种真正国际性的气氛。"},{"en":"I have tried to convey something of the flavour of the argument.","cn":"我试图表达某种类似论据的东西。"}]},"floor":{"media":{"uk":"media/uk/floor__gb_1.mp3","us":"media/us/floor__us_1.mp3"},"oxford":{"phon":"flɔː(r)","pos":"noun","senses":[{"en":"the surface of a room that you walk on","cn":"地板；地面"},{"en":"the bottom surface of a vehicle （","cn":"车厢内的）底板"}]},"collins":{"senses":[{"pos":"[N-COUNT 可数名词]","cn":"地面;地板；"},{"pos":"[N-COUNT 可数名词]","cn":"层;楼层；"}]},"examples":[{"en":"Opposition politicians registered their protest on the floor of the House.","cn":"反对党从政者在议院的议员席提出了抗议。"},{"en":"The alterations should give us extra floor space.","cn":"这些改动应该使我们有更大的居住面积。"}]},"flight":{"media":{"uk":"media/uk/flight__gb_1.mp3","us":"media/us/flight__us_1.mp3"},"oxford":{"phon":"flaɪt","pos":"noun","senses":[{"en":"a journey made by air, especially in a plane （","cn":"尤指乘飞机的）空中航行，航程"},{"en":"a plane making a particular journey","cn":"航班飞机；班机"}]},"collins":{"senses":[{"pos":"[N-COUNT 可数名词]","cn":"飞行;航行；"},{"pos":"[N-COUNT 可数名词]","cn":"航班;客机；"}]},"examples":[{"en":"mercy/relief flights (= planes taking help to countries where there is a war)","cn":"急救/救援班机（运送救援物资至发生战争的国家）"},{"en":"The bird is easily recognized in flight (= when it is flying) by the black band at the end of its tail.","cn":"这种鸟尾部末端有一条黑带，飞翔时很容易认出来。"}]},"flat":{"media":{"img":["media/pic/homes_comp.jpg","media/thumb/flat.jpg"],"uk":"media/uk/flat__gb_1.mp3","us":"media/us/flat__us_1.mp3"},"oxford":{"phon":"flæt","pos":"adjective","senses":[{"en":"having a level surface, not curved or sloping","cn":"水平的；平坦的"},{"en":"without any slopes or hills","cn":"平坦的"}]},"collins":{"senses":[{"pos":"[N-COUNT 可数名词]","cn":"(一间)公寓;(一套)单元房；"},{"pos":"[ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词]","cn":"平的;平展的;平滑的；"}]},"examples":[{"en":"It's a 30-year mortgage we just flat out can't handle.","cn":"这是一宗我们根本无法处理的 30 年按揭贷款业务。"},{"en":"Workers are working flat out to meet the rise in demand for new cars.","cn":"为满足对新轿车需求的增加，工人正全力以赴地工作。"}]},"flushes":{"oxford":{"phon":"flʌʃ","pos":"verb","senses":[{"en":"to become red, especially because you are embarrassed, angry or hot","cn":"发红；脸红"},{"en":"when a toilet flushes or you flush it, water passes through it to clean it, after a handle, etc. has been pressed","cn":"冲洗（抽水马桶）"}]},"collins":{"senses":[{"pos":"[VERB 动词]","cn":"脸红;脸发烫，发红；"},{"pos":"[V-ERG 及物/不及物动词]","cn":"(便后)冲(马桶)；"}]},"media":{"uk":"media/uk/flush__gb_1.mp3","us":"media/us/flush__us_1.mp3"}},"flamboyant":{"media":{"uk":"media/uk/flamboyant__gb_1.mp3","us":"media/us/flamboyant__us_1.mp3"},"oxford":{"phon":"flæmˈbɔɪənt","pos":"adj.","senses":[{"en":"different, confident and exciting in a way that attracts attention","cn":"炫耀的；卖弄的"},{"en":"brightly coloured and noticeable","cn":"艳丽的；绚丽夺目的"}]},"collins":{"senses":[{"pos":"[ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词]","cn":"引人注目的;炫耀的;时髦的；"}]},"examples":[{"en":"a flamboyant gesture/style/personality","cn":"炫耀的手势/作风/个性"},{"en":"flamboyant clothes/designs","cn":"艳丽的衣服；华丽的设计"}]},"fluff":{"media":{"uk":"media/uk/fluff__gb_1.mp3","us":"media/us/fluff__us_1.mp3"},"oxford":{"phon":"flʌf","pos":"noun","senses":[{"en":"small pieces of wool, cotton, etc. that gather on clothes and other surfaces （","cn":"衣服等上的）绒毛，蓬松毛团，尘团"},{"en":"soft animal fur or bird feathers, that is found especially on young animals or birds （","cn":"禽兽，尤指幼者的）绒毛"}]},"collins":{"senses":[{"pos":"[N-UNCOUNT 不可数名词]","cn":"(织物上的)绒毛，蓬松毛团;(小动物的)绒毛；"},{"pos":"[VERB 动词]","cn":"出错;搞砸；"}]},"examples":[{"en":"He completely fluffed an easy shot (= in sport).","cn":"一个唾手可得的进球机会被他搞砸了。"},{"en":"Most actors fluff their lines occasionally.","cn":"多数演员都会偶尔念错台词。"}]},"flour":{"oxford":{"phon":"ˈflaʊə(r)","pos":"noun","senses":[{"en":"a fine white or brown powder made from grain, especially wheat , and used in cooking for making bread, cakes, etc. （","cn":"尤指小麦的）面粉；（谷物磨成的）粉"},{"en":"to cover sth with a layer of flour","cn":"在 … 上撒（或覆以）面粉"}]},"collins":{"senses":[{"pos":"[N-MASS 物质名词]","cn":"面粉；"},{"pos":"[VERB 动词]","cn":"给…裹上面粉;在…上撒以面粉；"}]},"media":{"uk":"media/uk/flour__gb_1.mp3","us":"media/us/flour__us_1.mp3"},"examples":[{"en":"Roll the dough on a lightly floured surface.","cn":"揉生面团时，案板上要撒点面粉。"},{"en":"Roll the pastry out on a lightly floured board.","cn":"把面团放在撒有少许面粉的案板上擀平。"}]},"flame":{"oxford":{"phon":"fleɪm","pos":"noun","senses":[{"en":"a hot bright stream of burning gas that comes from sth that is on fire","cn":"火焰；火舌"},{"en":"a bright red or orange colour","cn":"鲜红色；橘红色；橙黄色"}]},"collins":{"senses":[{"pos":"[N-VAR 可变名词]","cn":"火焰;烈焰;火舌；"},{"pos":"[N-COUNT 可数名词]","cn":"谩骂性电子邮件;攻击性电子邮件；"}]},"media":{"uk":"media/uk/flame__gb_1.mp3","us":"media/us/flame__us_1.mp3","img":["media/ldoce/img/candle.jpg"]},"examples":[{"en":"The plane burst into flame(s) (= suddenly began burning strongly).","cn":"飞机突然猛烈燃烧起来。"},{"en":"The logs flamed on the hearth.","cn":"木柴在壁炉床里燃烧。"}]},"flexible":{"media":{"uk":"media/uk/flexible__gb_1.mp3","us":"media/us/flexible__us_1.mp3"},"oxford":{"phon":"ˈfleksəbl","pos":"adj.","senses":[{"en":"( approving ) able to change to suit new conditions or situations","cn":"能适应新情况的；灵活的；可变动的"},{"en":"able to bend easily without breaking","cn":"柔韧的；可弯曲的；有弹性的"}]},"collins":{"senses":[{"pos":"[ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词]","cn":"可弯曲的;柔韧的；"},{"pos":"[ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词]","cn":"易变通的;适应性强的;灵活的；"}]},"examples":[{"en":"Our plans need to be flexible enough to cater for the needs of everyone.","cn":"我们的计划必须能够变通，以满足每个人的需要。"},{"en":"You need to be more flexible and imaginative in your approach.","cn":"你的方法必须更加灵活，更富有想像力。"}]},"flatter":{"oxford":{"phon":"ˈflætə(r)","pos":"verb","senses":[{"en":"to say nice things about sb, often in a way that is not sincere, because you want them to do sth for you or you want to please them","cn":"奉承；讨好；向 … 谄媚"},{"en":"to choose to believe sth good about yourself and your abilities, especially when other people do not share this opinion","cn":"自命不凡"}]},"collins":{"senses":[{"pos":"[VERB 动词]","cn":"向…谄媚;奉承;讨好；"},{"pos":"[VERB 动词]","cn":"自认为;自以为是；"}]},"media":{"uk":"media/uk/flatter__gb_1.mp3","us":"media/us/flatter__us_1.mp3"},"examples":[{"en":"‘How will you manage without me?’ ‘Don't flatter yourself.’ “","cn":"没有我看你怎么办！” “别自以为了不起。”"},{"en":"The scoreline flattered England (= they did not deserve to get such a high score).","cn":"英格兰队在积分榜上的位置大大超过了其实力。"}]},"flow":{"media":{"uk":"media/uk/flow__gb_1.mp3","us":"media/us/flow__us_1.mp3"},"oxford":{"phon":"fləʊ","pos":"noun","senses":[{"en":"the steady and continuous movement of sth/sb in one direction","cn":"流；流动"},{"en":"the continuous production or supply of sth","cn":"持续生产；不断供应"}]},"collins":{"senses":[{"pos":"[VERB 动词]","cn":"流动;流向；"},{"pos":"[VERB 动词]","cn":"(人群或事物)流动，持续移动；"}]},"examples":[{"en":"You've interrupted my flow — I can't remember what I was saying.","cn":"你打断了我的话，我记不得我在说什么了。"},{"en":"The party got livelier as the drink began to flow.","cn":"开始尽兴畅饮时，聚会的气氛活跃起来。"}]},"flashes":{"oxford":{"phon":"flæʃ","pos":"verb","senses":[{"en":"to shine very brightly for a short time; to make sth shine in this way （","cn":"使）闪耀，闪光"},{"en":"to use a light to give sb a signal","cn":"用光发出信号"}]},"collins":{"senses":[{"pos":"[N-COUNT 可数名词]","cn":"闪耀;闪光；"},{"pos":"[V-ERG 及物/不及物动词]","cn":"使闪光,使闪耀;(尤指)频闪；"}]},"media":{"img":["media/pic/creativehobbies_comp.jpg","media/thumb/photography.jpg"],"uk":"media/uk/flash__gb_1.mp3","us":"media/us/flash__us_1.mp3"}},"flagging":{"oxford":{"phon":"flæɡ","pos":"noun","senses":[{"en":"a piece of cloth with a special coloured design on it that may be the symbol of a particular country or organization, or may have a particular meaning. A flag can be attached to a pole or held in the hand","cn":"旗"},{"en":"used to refer to a particular country or organization and its beliefs and values","cn":"旗帜（指某国家或组织及其信仰和价值观）"}]},"media":{"uk":"media/ldoce/hwd/bre/d/flagging0205.mp3","us":"media/ldoce/hwd/ame/1/laadflagging.mp3"}},"flavoured":{"oxford":{"phon":"ˈfleɪvəd","pos":"adj.","senses":[{"en":"having the type of flavour mentioned","cn":"有 … 味道的"},{"en":"having had flavour added to it","cn":"添加了味道的"}]},"collins":{"senses":[{"pos":"[ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词]","cn":"添加了调料的；"}]},"media":{"uk":"media/uk/flavoured__gb_1.mp3","us":"media/us/flavoured__us_1.mp3"},"examples":[{"en":"flavoured yogurt","cn":"有添加味道的酸奶"},{"en":"lemon-flavoured sweets/candy","cn":"柠檬味糖果"}]},"flags":{"oxford":{"phon":"flæɡ","pos":"noun","senses":[{"en":"a piece of cloth with a special coloured design on it that may be the symbol of a particular country or organization, or may have a particular meaning. A flag can be attached to a pole or held in the hand","cn":"旗"},{"en":"used to refer to a particular country or organization and its beliefs and values","cn":"旗帜（指某国家或组织及其信仰和价值观）"}]}},"flattered":{"oxford":{"phon":"ˈflætə(r)","pos":"verb","senses":[{"en":"to say nice things about sb, often in a way that is not sincere, because you want them to do sth for you or you want to please them","cn":"奉承；讨好；向 … 谄媚"},{"en":"to choose to believe sth good about yourself and your abilities, especially when other people do not share this opinion","cn":"自命不凡"}]},"collins":{"senses":[{"pos":"[ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词]","cn":"(因受重视而)感到满意的，觉得荣幸的；"},{"pos":"[ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词]","cn":"(在正式场合表示感谢)不胜荣幸的，深感荣幸的；"}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41flattered.mp3","us":"media/ldoce/hwd/ame/f/ld41flattered.mp3"},"examples":[{"en":"We were flattered by all the attention.","cn":"受到如此关注﹐我们深感荣幸。"}]},"flaws":{"oxford":{"phon":"flɔː","pos":"noun","senses":[{"en":"a mistake in sth that means that it is not correct or does not work correctly","cn":"错误；缺点"},{"en":"a crack or fault in sth that makes it less attractive or valuable","cn":"裂痕；裂隙；瑕疵"}]}},"fluffy":{"media":{"uk":"media/uk/fluffy__gb_1.mp3","us":"media/us/fluffy__us_1.mp3"},"oxford":{"phon":"ˈflʌfi","pos":"adj.","senses":[{"en":"like fluff; covered in fluff","cn":"绒毛般的；覆有绒毛的"},{"en":"soft, light and containing air","cn":"松软的"}]},"collins":{"senses":[{"pos":"[ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词]","cn":"绒毛似的;松软的;蓬松的；"},{"pos":"[ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词]","cn":"(食物)松软的；"}]},"examples":[{"en":"Beat the butter and sugar until soft and fluffy.","cn":"搅打奶油和糖直到松软为止。"},{"en":"a fluffy argument","cn":"一个无说服力的论据"}]},"flames":{"oxford":{"phon":"fleɪm","pos":"noun","senses":[{"en":"a hot bright stream of burning gas that comes from sth that is on fire","cn":"火焰；火舌"},{"en":"a bright red or orange colour","cn":"鲜红色；橘红色；橙黄色"}]}},"flaw":{"oxford":{"phon":"flɔː","pos":"noun","senses":[{"en":"a mistake in sth that means that it is not correct or does not work correctly","cn":"错误；缺点"},{"en":"a crack or fault in sth that makes it less attractive or valuable","cn":"裂痕；裂隙；瑕疵"}]},"collins":{"senses":[{"pos":"[N-COUNT 可数名词]","cn":"错误;谬误；"},{"pos":"[N-COUNT 可数名词]","cn":"性格中的缺点，弱点；"}]},"media":{"uk":"media/uk/flaw__gb_1.mp3","us":"media/us/flaw__us_1.mp3"},"examples":[{"en":"The report reveals fatal flaws in security at the airport.","cn":"报告揭示了机场安全的致命缺陷。"},{"en":"The argument is full of fundamental flaws.","cn":"这段论述充满根本性的错误。"}]},"flesh":{"oxford":{"phon":"fleʃ","pos":"noun","senses":[{"en":"the soft substance between the skin and bones of animal or human bodies （","cn":"动物或人的）肉"},{"en":"the skin of the human body （","cn":"人体的）皮肤"}]},"collins":{"senses":[{"pos":"[N-UNCOUNT 不可数名词]","cn":"肉；"},{"pos":"[N-UNCOUNT 不可数名词]","cn":"肉体;肌肤；"}]},"media":{"uk":"media/uk/flesh__gb_1.mp3","us":"media/us/flesh__us_1.mp3","img":["media/ldoce/img/kiwi.jpg"]},"examples":[{"en":"The strength of the book is that it puts flesh on the bare bones of this argument.","cn":"本书的优点是对这个论点的基本事实有翔实的论述。"},{"en":"These points were fleshed out in the later parts of the speech.","cn":"这几点在演讲的后面部分已得到充实。"}]},"fluency":{"media":{"uk":"media/uk/fluency__gb_1.mp3","us":"media/us/fluency__us_1.mp3"},"oxford":{"phon":"ˈfluːənsi","pos":"noun","senses":[{"en":"the quality of being able to speak or write a language, especially a foreign language, easily and well （","cn":"尤指外语）流利，流畅"},{"en":"the quality of doing sth in a smooth and skilful way","cn":"熟练自如；流畅"}]},"examples":[{"en":"Fluency in French is required for this job.","cn":"这个工作要求法语熟练自如。"},{"en":"The team lacked fluency during the first half.","cn":"该队在上半场打得不够流畅。"}]},"fleet":{"media":{"uk":"media/uk/fleet__gb_1.mp3","us":"media/us/fleet__us_1.mp3"},"oxford":{"phon":"fliːt","pos":"noun","senses":[{"en":"a group of military ships commanded by the same person","cn":"舰队"},{"en":"a group of ships fishing together","cn":"捕鱼船队"}]},"collins":{"senses":[{"pos":"[N-COUNT 可数名词]","cn":"船队;舰队；"},{"pos":"[N-COUNT 可数名词]","cn":"(尤指同一机构或统一行动的)车队；"}]},"examples":[{"en":"the company's new fleet of vans","cn":"公司的新客货车队"},{"en":"a reduction in the size of the British fleet","cn":"英国海军的裁减"}]},"flush":{"media":{"uk":"media/uk/flush__gb_1.mp3","us":"media/us/flush__us_1.mp3"},"oxford":{"phon":"flʌʃ","pos":"verb","senses":[{"en":"to become red, especially because you are embarrassed, angry or hot","cn":"发红；脸红"},{"en":"when a toilet flushes or you flush it, water passes through it to clean it, after a handle, etc. has been pressed","cn":"冲洗（抽水马桶）"}]},"collins":{"senses":[{"pos":"[VERB 动词]","cn":"脸红;脸发烫，发红；"},{"pos":"[V-ERG 及物/不及物动词]","cn":"(便后)冲(马桶)；"}]},"examples":[{"en":"in the first flush of youth/enthusiasm/romance","cn":"在青春活力旺盛时期；在热情高涨阶段；在热恋的初期"},{"en":"Drinking lots of water will help to flush toxins out of the body.","cn":"大量饮水有助于清除体内毒素。"}]},"floors":{"oxford":{"phon":"flɔː(r)","pos":"noun","senses":[{"en":"the surface of a room that you walk on","cn":"地板；地面"},{"en":"the bottom surface of a vehicle （","cn":"车厢内的）底板"}]}},"flannels":{"oxford":{"phon":"ˈflænl","pos":"noun","senses":[{"en":"a type of soft light cloth, containing cotton or wool, used for making clothes","cn":"法兰绒"},{"en":"a small piece of cloth used for washing yourself （","cn":"洗擦身体用的）毛巾"}]}},"fleeing":{"oxford":{"phon":"fliː","pos":"verb","senses":[{"en":"to leave a person or place very quickly, especially because you are afraid of possible danger","cn":"迅速离开；（尤指害怕有危险而）逃避，逃跑"}]}},"flocks":{"oxford":{"phon":"flɒk","pos":"noun","senses":[{"en":"a group of sheep, goats or birds of the same type （","cn":"羊或鸟）群"},{"en":"a large group of people, especially of the same type （","cn":"尤指同类人的）一大群"}]}},"floods":{"oxford":{"phon":"flʌd","pos":"noun","senses":[{"en":"a large amount of water covering an area that is usually dry","cn":"洪水；水灾"},{"en":"a very large number of things or people that appear at the same time","cn":"大批，大量（的人或事物）"}]}},"flattening":{"oxford":{"phon":"ˈflætn","pos":"verb","senses":[{"en":"to become or make sth become flat or flatter （","cn":"使）变平；把 … 弄平"},{"en":"to destroy or knock down a building, tree, etc.","cn":"摧毁，推倒，弄倒（建筑物、树木等）"}]}},"flicks":{"oxford":{"phon":"flɪk","pos":"verb","senses":[{"en":"to hit sth with a sudden quick movement, especially using your finger and thumb together, or your hand （","cn":"尤指用手指或手快速地）轻击，轻拍，轻拂，轻弹"},{"en":"to move or make sth move with sudden quick movements （","cn":"使）突然快速移动"}]}},"floorboards":{"oxford":{"phon":"ˈflɔːbɔːd","pos":"noun","senses":[{"en":"a long flat piece of wood in a wooden floor","cn":"木质地板条"}]}},"flats":{"oxford":{"phon":"flæt","pos":"adjective","senses":[{"en":"having a level surface, not curved or sloping","cn":"水平的；平坦的"},{"en":"without any slopes or hills","cn":"平坦的"}]}},"flights":{"oxford":{"phon":"flaɪt","pos":"noun","senses":[{"en":"a journey made by air, especially in a plane （","cn":"尤指乘飞机的）空中航行，航程"},{"en":"a plane making a particular journey","cn":"航班飞机；班机"}]}},"flashed":{"oxford":{"phon":"flæʃ","pos":"verb","senses":[{"en":"to shine very brightly for a short time; to make sth shine in this way （","cn":"使）闪耀，闪光"},{"en":"to use a light to give sb a signal","cn":"用光发出信号"}]}},"flagstones":{"oxford":{"phon":"ˈflæɡstəʊn","pos":"noun","senses":[{"en":"a large flat square piece of stone that is used for floors, paths, etc.","cn":"石板（方形，用于铺地面、小径等）"}]}},"floats":{"oxford":{"phon":"fləʊt","pos":"verb","senses":[{"en":"to move slowly on water or in the air","cn":"浮动；漂流；飘动；飘移"},{"en":"to stay on or near the surface of a liquid and not sink","cn":"浮；漂浮"}]}},"flourishing":{"oxford":{"phon":"ˈflʌrɪʃ","pos":"verb","senses":[{"en":"to develop quickly and be successful or common","cn":"繁荣；昌盛；兴旺"},{"en":"to grow well; to be healthy and happy","cn":"茁壮成长；健康幸福"}]}},"flowers":{"oxford":{"phon":"ˈflaʊə(r)","pos":"noun","senses":[{"en":"the coloured part of a plant from which the seed or fruit develops. Flowers usually grow at the end of a stem and last only a short time.","cn":"花；花朵"},{"en":"a plant grown for the beauty of its flowers","cn":"开花植物"}]}},"flourished":{"oxford":{"phon":"ˈflʌrɪʃ","pos":"verb","senses":[{"en":"to develop quickly and be successful or common","cn":"繁荣；昌盛；兴旺"},{"en":"to grow well; to be healthy and happy","cn":"茁壮成长；健康幸福"}]}},"flowing":{"oxford":{"phon":"fləʊ","pos":"noun","senses":[{"en":"the steady and continuous movement of sth/sb in one direction","cn":"流；流动"},{"en":"the continuous production or supply of sth","cn":"持续生产；不断供应"}]},"media":{"uk":"media/ldoce/hwd/bre/d/flowing0205.mp3","us":"media/ldoce/hwd/ame/3/flowing.mp3"},"examples":[{"en":"She had pale skin and dark, flowing hair.","cn":"她皮肤白皙﹐黑发飘飘。"},{"en":"long, flowing robes","cn":"飘逸的长袍"}]},"flare":{"collins":{"senses":[{"pos":"N-COUNT","cn":"闪光信号灯;照明弹","en":"A flare is a small device that produces a bright flame. Flares are used as signals, for example on ships. ...a ship which had fired a distress . 发出遇险信号弹的一艘船"},{"pos":"VERB","cn":"(火)突然烧旺，突然熊熊燃烧","en":"If a fire flares , the flames suddenly become larger. 【语法信息】：V 【语法信息】：V P Camp fires d like beacons in the dark. 营火突然熊熊燃烧起来，看上去就像黑暗中的航标灯。 Flare up means the same as flare . Don't spill too much fat on the barbecue as it could up. 不要在烤肉上浇太多的"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to start burning accidentally","cn":""},{"en":"to suddenly start burning and produce a lot of flames that cause serious damage","cn":""},{"en":"if a building or vehicle goes up or goes up in flames , it starts burning very quickly and usually is destroyed by fire","cn":""}]},"vocab":{"pos":"1 n v 2 n v 3 n 4 n","senses":[{"en":"A flare is a sudden burst of light. The flare of a lit match in the dark night is strangely beautiful."}]},"collocations":{"phrases":["ADV. suddenly Anger suddenly flared in his eyes. | briefly A light flared briefly, then went out. | up Violence flared up in the capital las","PHRASES flare into life The fire flared into life again."]},"media":{"uk":"media/ldoce/hwd/bre/b/flair0205.mp3","us":"media/ldoce/hwd/ame/7/flair.mp3"},"examples":[{"en":"The ship sent up distress flares to attract the attention of the coastguard.","cn":"这艘船点起了遇险信号以引起海岸警卫队的注意。"},{"en":"‘You should have told me!’ she flared at him. “","cn":"你应该告诉我的！”她气冲冲地对他说。"}]},"flourish":{"collins":{"senses":[{"pos":"VERB","cn":"繁荣;兴盛;兴旺","en":"If something flourishes , it is successful, active, or common, and developing quickly and strongly. 【语法信息】：V Business ed and within six months they were earning 18,000 roubles a day... 生意红火起来，不出6 个月他们就可以每天赚 18,000 卢布了。 Racism and crime stil"},{"pos":"VERB","cn":"(植物或动物)长势好，茁壮成长","en":"If a plant or animal flourishes , it grows well or is healthy because the conditions are right for it. 【语法信息】：V The plant es particularly well in slightly harsher climes. 这种植物在气候条件稍差一点的地区长势尤其好。"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to show someone or something that you are proud of to other people","cn":""},{"en":"to let people see your valuable possessions so that they know you are rich or successful, in a way that annoys people","cn":""},{"en":"to wave something in your hand in order to make people notice it 〔","cn":"为引起注意而〕挥动〔手中的东西〕"}]},"vocab":{"pos":"1 v 2 n v 3 n","senses":[{"en":"A flourish is an extra touch — a trumpet's \"ta-ta-da!\" announcing a king's entrance, a fancy carving atop an otherwise utilitarian pillar, a wave of a flag or a cheerleader's pompom."}]},"collocations":{"phrases":["ADJ. final | dramatic, rhetorical, theatrical a speech full of rhetorical flourishes","VERB + FLOURISH end in/with, finish with | start (off) with | sign with Bill signed on the bottom line with a flourish.","PREP. with a ~ With a final flourish she laid down her pen.","PHRASES a flourish of trumpets"]},"media":{"uk":"media/ldoce/hwd/bre/b/flourish_v0205.mp3","us":"media/ldoce/hwd/ame/1/laadflourish_.mp3"},"examples":[{"en":"The season ended with a flourish for Rooney, when he scored in the final minute of the match.","cn":"鲁尼本赛季华丽收关：他在比赛最后一分钟射进一球。"},{"en":"Few businesses are flourishing in the present economic climate.","cn":"在目前的经济气候下，很少有企业兴旺发达。"}]},"flank":{"collins":{"senses":[{"pos":"N-COUNT","cn":"胁;胁腹","en":"An animal's flank is its side, between the ribs and the hip. He put his hand on the dog's . 他把手放在狗的胁腹上。"},{"pos":"N-COUNT","cn":"(军队的)侧翼，翼侧","en":"A flank of an army or navy force is one side of it when it is organized for battle. The assault element, led by Captain Ramirez, opened up from their right . 拉米雷斯上尉率领的突击队从他们的右翼开火。"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the side of an animal’s or person’s body, between the rib s and the hip","cn":"胁部﹐胁腹"},{"en":"the side of an army in a battle, or a sports team when playing 〔","cn":"军队或球队的〕侧翼"},{"en":"the side of a hill, mountain, or very large building 〔","cn":"山或大型建筑物的〕侧面"}]},"vocab":{"pos":"n v","senses":[{"en":"A flank is the side of something, whether of beef or a military formation."}]},"collocations":{"phrases":["ADJ. left, right | north, northern, etc. | lower the lower flanks of Vesuvius | mountain","VERB + FLANK attack They decided to attack their enemy's southern flank. | defend, protect | expose West Ham exposed the right flank of Norw","FLANK + NOUN attack","PREP. along a/the ~ along the eastern flank of Greenland | down the ~ a beautiful pass down the right flank | on a/the ~ The army was attack"]},"media":{"uk":"media/ldoce/hwd/bre/a/flank_n0205.mp3","us":"media/ldoce/hwd/ame/0/flank1.mp3"},"examples":[{"en":"They drove through the cotton fields that flanked Highway 17.","cn":"他们驾车穿过了 17 号公路侧面的棉田。"},{"en":"She left the courtroom flanked by armed guards.","cn":"她在武装警卫护送下离开法庭。"}]},"flavouring":{"collins":{"senses":[{"pos":"N-VAR","cn":"调味品;调料","en":"Flavourings are substances that are added to food or drink to give it a particular taste. Our range of herbal teas contain no preservatives, colourings or artificial s. 我们这一系列的药草茶不含防腐剂、色素以及人工调味品。 ...lemon flavoring. 柠檬调料"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a substance used to give something a particular flavour or increase its flavour","cn":"调味品﹐调味香料"}]},"collocations":{"phrases":["ADJ. artificial, natural This product contains only natural flavourings. | food | peppermint, vanilla, etc.","QUANT. drop Add a few drops of peppermint flavouring.","VERB + FLAVOURING contain | use We don't use any artificial flavourings in our products. | add"]},"media":{"uk":"media/ldoce/hwd/bre/a/brelasdeflavouring.mp3","us":"media/ldoce/hwd/ame/1/amelasdeflavouring.mp3"},"examples":[{"en":"This food contains no artificial flavourings.","cn":"这种食品不含人工调味品。"},{"en":"orange/vanilla flavouring","cn":"橙/香草调味香料"}]},"flex":{"collins":{"senses":[{"pos":"N-VAR","cn":"(电器用)花线，皮线","en":"A flex is an electric cable containing two or more wires that is connected to an electrical appliance. 【语域标签】：mainly BRIT 主英"},{"pos":"VERB","cn":"活动，屈伸(肌肉或身体某一部分)","en":"If you flex your muscles or parts of your body, you bend, move, or stretch them for a short time in order to exercise them. 【语法信息】：V n He slowly ed his muscles and tried to stand. 他缓慢地活动了一下肌肉，想尽量站起来。"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to tighten your muscles or bend part of your body","cn":"收紧〔肌肉〕﹔屈曲〔身体部位〕"},{"en":"to show your ability to do something, especially your skill or power","cn":"展示自己的才能〔尤指技艺或力量〕"},{"en":"an electrical wire covered with plastic, used to connect electrical equipment to an electricity supply 〔","cn":"电器用〕花线﹐皮线"}]},"collocations":{"phrases":["ADJ. long | trailing Long trailing flexes are a serious trip hazard. | electric/electical | kettle, telephone, etc.","QUANT. length","VERB + FLEX cut Side cutters are useful for cutting electrical flex to length."]},"media":{"uk":"media/ldoce/hwd/bre/c/flex_v0205.mp3","us":"media/ldoce/hwd/ame/c/flex.mp3","img":["media/thumb/flex.jpg"]},"examples":[{"en":"He stood on the side of the pool flexing his muscles.","cn":"他站在游泳池旁活动肌肉。"},{"en":"to flex your fingers/feet/legs","cn":"活动手指/双脚/双腿"}]},"floorboard":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a board in a wooden floor","cn":"一块木地板"},{"en":"the floor in a car 〔","cn":"汽车的〕底板"}]},"collocations":{"phrases":["ADJ. wooden | bare | polished | loose | creaking, squeaky","VERB + FLOORBOARD lay The builders are still laying the floorboards. | lift (up) Lift some loose floorboards to get at the pipes.","FLOORBOARD + VERB creak The wooden floorboards creaked as he walked down the corridor.","PREP. beneath/under/underneath the ~ They said that he kept his money under the floorboards.","PHRASES a gap between/in the floorboards She could hear voices through the gaps in the floorboards."]},"media":{"uk":"media/ldoce/hwd/bre/e/floorboard0205.mp3","us":"media/ldoce/hwd/ame/5/floorboard.mp3"},"examples":[{"en":"He had his foot to the floorboard (= was going very fast).","cn":"他猛踩油门飞速驾驶。"},{"en":"bare/polished floorboards","cn":"素面/打了蜡的地板"}]},"flicker":{"collins":{"senses":[{"pos":"VERB","cn":"(灯光等)闪烁，摇曳","en":"If a light or flame flickers , it shines unsteadily. 【语法信息】：V Fluorescent lights ed, and then the room was brilliantly, blindingly bright... 荧光灯闪了几下，接着屋子里豁然大亮，刺得人睁不开眼。 A television ed in the corner. 电视机在角落里时明时暗地变换着画面。 Flicker is also a noun"},{"pos":"N-COUNT","cn":"(情感的)闪现，一闪而过","en":"If you experience a flicker of emotion, you feel that emotion only for a very short time, and not very strongly. 【搭配模式】：usu sing He felt a of regret... 他突然感到一丝悔意。 He looked at me, a of amusement in his cold eyes. 他看着我，冷酷的眼神里闪过一丝嘲笑。"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to produce bright light","cn":""},{"en":"to shine brightly for a very short time, or to shine on and off very quickly many times","cn":""},{"en":"to shine with a very strong light which hurts your eyes","cn":""}]},"vocab":{"pos":"1 v n 2 v n 3 n","senses":[{"en":"To flicker is to flash on and off at random. If your computer screen is flickering right now, you are probably having trouble reading this."}]},"collocations":{"phrases":["ADJ. faint, slight, small, tiny She caught the faintest flicker of amusement on his face. | brief, momentary | last (often figurative) The s","VERB + FLICKER give The candle gave one last flicker and went out. | show | catch, notice, see | detect, feel She felt a brief flicker of je","FLICKER + VERB cross sth A flicker of guilt crossed his face. | catch your eye A flicker of movement caught her eye and she turned her head.","PREP. with a ~ of &lsquo;He'll soon be here,&rsquo; she thought, with a flicker of excitement. | without a ~ of She spoke without any flicke","PHRASES the flicker of a candle/flame The brief flicker of a candle flame caught our eyes. | the flicker of an eyelid, a flicker of sb's/the"]},"media":{"uk":"media/ldoce/hwd/bre/6/flicker_v0205.mp3","us":"media/ldoce/hwd/ame/5/flicker1.mp3"},"examples":[{"en":"Her eyelids flickered as she slept.","cn":"她睡觉时眼睑不停地眨动。"},{"en":"the flickering screen of the television","cn":"图像在抖动的电视荧光屏"}]},"flee":{"collins":{"senses":[{"pos":"VERB","cn":"逃离;逃避","en":"If you flee from something or someone, or flee a person or thing, you escape from them. 【语法信息】：V 【语法信息】：V prep/adv 【语法信息】：V n 【搭配模式】：no passive 【FIELD标签】：WRITTEN 笔语 He slammed the bedroom door behind him and fled... 他把卧室房门重重地关上，然后逃跑了。 He fl"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to leave a place when someone is trying to catch you or stop you, or when there is a dangerous situation","cn":""},{"en":"to escape from someone who is chasing you, especially when there is no chance that you will be caught. Get away is more informal than escape","cn":""},{"en":"to escape from someone who is holding you","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"If you bolt, scram, skedaddle, or get the heck of out Dodge, you flee . You run away fast. Don’t confuse flee with \"flea.\" They sound alike, but the second kind is an insect whose bites make you itch."}]},"collocations":{"phrases":["ADV. abroad, across the border, into exile Hundreds of refugees fled across the border to escape the fighting. | north, south, etc. | in pan","VERB + FLEE be forced to, have to They were forced to flee the country. | try to | manage to | turn They turned and fled when they saw the g","PREP. from She dropped the phone and fled from the office. | into/to They fled to Britain when the war started.","PHRASES flee empty-handed When the police arrived the burglars fled empty-handed. | flee for your life She had to flee for her life when sol"]},"media":{"uk":"media/ldoce/hwd/bre/0/flee0205.mp3","us":"media/ldoce/hwd/ame/4/flea.mp3"},"examples":[{"en":"He fled to London after an argument with his family.","cn":"他与家人争吵以后离家去了伦敦。"},{"en":"He was caught trying to flee the country.","cn":"他企图逃离该国时被抓住了。"}]},"flashback":{"collins":{"senses":[{"pos":"N-COUNT","cn":"(电影、小说、戏剧中的)闪回，倒叙","en":"In a film, novel, or play, a flashback is a scene that returns to events in the past. 【搭配模式】：oft N to n There is even a to the murder itself. 甚至有一段关于谋杀本身的闪回。"},{"pos":"N-COUNT","cn":"(往事的)突然重现，闪回，再现","en":"If you have a flashback to a past experience, you have a sudden and very clear memory of it. 【搭配模式】：oft N to n He has recurring s to the night his friends died. 他反复想起朋友们死去的那个夜晚的情形。"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a scene in a film, play, book etc that shows something that happened before that point in the story 〔","cn":"电影的〕闪回镜头﹔〔戏剧的〕闪回场景﹔〔书中的〕倒叙"},{"en":"a sudden very clear memory of something that happened to you in the past 〔","cn":"往事的〕闪回﹐突然重现"},{"en":"an occasion when someone has the same bad feeling that they had when they took an illegal drug in the past 〔","cn":"在未吸毒时产生的〕药效幻觉重现"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"A flashback is a transition in a story to an earlier time, that interrupts the normal chronological order of events. A flashback in a movie might show what happened when a character was younger."}]},"collocations":{"phrases":["ADJ. sudden","VERB + FLASHBACK get, have","PREP. in (a) ~ The story is told in flashback. | ~ to I had a sudden flashback to the time immediately after the war."]},"media":{"uk":"media/ldoce/hwd/bre/c/flashback0205.mp3","us":"media/ldoce/hwd/ame/a/flashback.mp3"},"examples":[{"en":"The events that led up to the murder were shown in a series of flashbacks.","cn":"通过一系列倒叙展现出了导致谋杀的各个情节。"},{"en":"The reader is told the story in flashback.","cn":"故事是以倒叙手法向读者讲述的。"}]},"flair":{"collins":{"senses":[{"pos":"N-SING","cn":"天资;天赋;天分","en":"If you have a flair for a particular thing, you have a natural ability to do it well. 【搭配模式】：N for n ...a friend who has a for languages. 有语言天赋的朋友"},{"pos":"N-UNCOUNT","cn":"才华;资质;创意","en":"If you have flair , you do things in an original, interesting, and stylish way. 【语用信息】：approval Their work has all the usual punch, panache and you'd expect. 他们的作品一如既往地引人入胜、气韵潇洒、新颖别致，不会让你失望。"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an ability to do something well, especially because you have learned and practised it","cn":""},{"en":"a natural ability to do something well which can be developed with practice","cn":""},{"en":"very great ability, which only a few people have","cn":""}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"Use the word flair to refer to someone’s knack or natural talent for something. Someone might have a flair for throwing fantastic parties, or a flair for solving complex math problems."}]},"collocations":{"phrases":["ADJ. considerable, great | real | natural | artistic, creative, design, entrepreneurial, imaginative","VERB + FLAIR have She has a natural flair for languages. | show | lack His designs are all right, but he lacks artistic flair. | develop","PREP. with ~ jazz guitarists who improvise with flair | ~ for an activist with a flair for publicity"]},"media":{"uk":"media/ldoce/hwd/bre/b/flair0205.mp3","us":"media/ldoce/hwd/ame/7/flair.mp3"},"examples":[{"en":"He has a flair for languages.","cn":"他有学语言的天分。"},{"en":"She dresses with real flair.","cn":"她衣着甚有品味。"}]},"flick":{"collins":{"senses":[{"pos":"V-ERG","cn":"轻弹;轻击;轻快地移动","en":"If something flicks in a particular direction, or if someone flicks it, it moves with a short, sudden movement. 【语法信息】：V prep/adv 【语法信息】：V n prep/adv 【语法信息】：Also V 【搭配模式】： a N His tongue ed across his lips... 他的舌头迅速舔了一下嘴唇。 The man's gun ed "},{"pos":"VERB","cn":"轻弹;轻拭","en":"If you flick something away, or off something else, you remove it with a quick movement of your hand or finger. 【语法信息】：V n from/off n 【语法信息】：V n away Shirley ed a speck of fluff from the sleeve of her black suit... 雪莉弹掉了黑色套装袖子上的一点小绒毛。 Alan "}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make something small and light go forward through the air with a quick movement of your thumb and finger","cn":""},{"en":"to make something move away by hitting or pushing it suddenly or quickly, especially with your thumb and finger 〔","cn":"尤指用大拇指和另一手指〕弹﹐拂"},{"en":"to move with a sudden quick movement, or to make something move in this way","cn":"晃动﹐拍动﹔抖掉"}]},"vocab":{"pos":"1 v n 2 v 3 v 4 n","senses":[{"en":"A flick is a quick, short movement, usually coming from the wrist or hand. There used to be a \" Flick a Bic \" cigarette ad: cigarettes are awful, but starting a lighter is a classic flick ."}]},"collocations":{"phrases":["ADV. casually | nervously | quickly | away, back","PREP. across His tongue flicked nervously across dry lips. | from He casually flicked away some dust from his jacket. | off She flicked the ","PHRASES flick sth open She snatched up her briefcase and flicked it open. PHRASAL VERBS flick through sth","ADV. absent-mindedly, casually, idly She flicked idly through a magazine. | quickly"]},"media":{"uk":"media/ldoce/hwd/bre/b/brelasdeflick.mp3","us":"media/ldoce/hwd/ame/8/flick1.mp3"},"examples":[{"en":"I've only had time to flick through your report but it seems to be fine.","cn":"我的时间不多，只是草草翻阅了一下你的报告，但似乎还不错。"},{"en":"Flicking through the channels, I came across an old war movie.","cn":"我快速浏览电视频道，发现有一部老的战争片在播放。"}]},"flop":{"collins":{"senses":[{"pos":"VERB","cn":"猛然坐下;重重地坐下","en":"If you flop into a chair, for example, you sit down suddenly and heavily because you are so tired. 【语法信息】：V prep/adv Bunbury ped down upon the bed and rested his tired feet... 邦伯里重重地倒在了床上，让他疲惫的双脚休息一下。 She ped, exhausted, on to a sofa. 她精疲力竭"},{"pos":"VERB","cn":"凌乱地垂下;猛落下","en":"If something flops onto something else, it falls there heavily or untidily. 【语法信息】：V prep/adv The briefcase ped onto the desk... 公文包重重地落在桌上。 His hair ped over his left eye. 他的头发凌乱地垂在左眼前。"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to be completely unsuccessful, in a way that makes people feel disappointed and embarrassed","cn":""},{"en":"if an event, especially a social event, is a disaster , it makes people feel angry, disappointed, or embarrassed, instead of being enjoyable","cn":""},{"en":"if a situation or event is a shambles , it is completely unsuccessful because it has been very badly planned or organized","cn":""}]},"collocations":{"phrases":["ADJ. almighty, big, resounding, spectacular The show was the biggest flop in TV history. | complete | expensive The concert may prove an exp"]},"media":{"uk":"media/ldoce/hwd/bre/c/flop_las3_br.mp3","us":"media/ldoce/hwd/ame/9/flop1.mp3"},"examples":[{"en":"Exhausted, he flopped down into a chair.","cn":"他筋疲力尽，一屁股坐到椅子上。"},{"en":"Her hair flopped over her eyes.","cn":"她的头发耷拉下来遮住了眼睛。"}]},"flout":{"collins":{"senses":[{"pos":"VERB","cn":"无视，藐视，轻视(法律等)","en":"If you flout something such as a law, an order, or an accepted way of behaving, you deliberately do not obey it or follow it. 【语法信息】：V n ...illegal campers who persist in ing the law... 一向对法律熟视无睹的非法露营者 Building regulations have been habitua"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to not obey a person, order, rule, or law","cn":""},{"en":"to not obey a law or rule","cn":""},{"en":"to deliberately refuse to obey a rule or law, or what someone in authority tells you to do","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To flout is to scorn or show contempt for. \"I flout the law and the concept of civilian safety by making a concerted effort to jaywalk every time I cross a street.\""}]},"collocations":{"phrases":["ADV. deliberately, openly The protesters have openly flouted the law."]},"media":{"uk":"media/ldoce/hwd/bre/d/flout_las3_br.mp3","us":"media/ldoce/hwd/ame/4/flout.mp3"},"examples":[{"en":"Motorists regularly flout the law.","cn":"驾车者经常无视法律。"},{"en":"to flout authority/convention","cn":"公然藐视权威/惯例"}]},"flattery":{"collins":{"senses":[{"pos":"N-UNCOUNT","cn":"奉承;阿谀;恭维","en":"Flattery consists of flattering words or behaviour. 【语用信息】：disapproval He is ambitious and susceptible to . 他雄心勃勃，而且很喜欢听别人的恭维话。"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"things you say to someone to show that you admire them or approve of what they have done","cn":""},{"en":"what you say when you tell someone they look nice or they have done something well","cn":""},{"en":"nice things that you say about someone, which may not be true, in order to get something that you want from them","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Flattery is excessive praise. If you're hoping to borrow your brother's car, be careful not to overdo it when you compliment his haircut, new shoes, and singing voice — he knows flattery when he sees it."}]},"collocations":{"phrases":["ADJ. artificial","VERB + FLATTERY use Salespeople are often accused of using artificial flattery. | fall for She falls for his flattery every time.","PREP. through ~ He thinks he can get his way through flattery. | with ~ She persuaded him with flattery."]},"media":{"uk":"media/ldoce/hwd/bre/e/flattery0205.mp3","us":"media/ldoce/hwd/ame/7/flattery.mp3"},"examples":[{"en":"You're too intelligent to fall for his flattery.","cn":"你很聪明，不会受他的阿谀奉承所惑。"}]},"flail":{"collins":{"senses":[{"pos":"V-ERG","cn":"(四肢)拼命乱动,使劲乱摆","en":"If your arms or legs flail or if you flail them about, they wave about in an energetic but uncontrolled way. 【语法信息】：V 【语法信息】：V n 【语法信息】：V P His arms were ing in all directions... 他的手臂胡乱挥舞着。 He gave a choked cry, ed his arms wildly for a mom"},{"pos":"N-COUNT","cn":"连枷(脱粒用的农具)","en":"A flail is a tool which consists of a piece of wood or metal that can swing freely from a handle. Flails are used to beat crops such as corn in order to separate the grain from the rest of the plant."}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to wave your arms or legs in an uncontrolled way","cn":"手脚乱动﹔胡乱地挥[踢]"},{"en":"to beat someone or something violently, usually with a stick 〔","cn":"用棍子〕敲打﹐殴打"},{"en":"to beat grain with a flail","cn":"用连枷打（谷）"}]},"vocab":{"pos":"n v","senses":[{"en":"To flail means to wave around wildly. If you are stranded on a deserted island and you see a ship in the distance, it’s a good idea to flail your arms in the air to get the captain’s attention."}]},"collocations":{"phrases":["ADV. desperately, helplessly, wildly She ran along, her arms flailing wildly. | about, around He flailed about in the water, shouting &lsquo"]},"media":{"uk":"media/ldoce/hwd/bre/d/flail_v0205.mp3","us":"media/ldoce/hwd/ame/9/flail1.mp3"},"examples":[{"en":"The boys flailed around on the floor.","cn":"男孩子们在地板上任意地动来动去。"},{"en":"He was running along, his arms flailing wildly.","cn":"他向前跑，拼命摆动双臂。"}]},"flammable":{"collins":{"senses":[{"pos":"ADJ-GRADED","cn":"易燃的;可燃的","en":"Flammable chemicals, gases, cloth, or other things catch fire and burn easily. ... liquids such as petrol or paraffin. 汽油和煤油之类的易燃液体"}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"to be able to be burned","cn":""},{"en":"materials, chemicals, or gases that are flammable or inflammable will start burning very easily and quickly, so they can be dangerous","cn":""},{"en":"something that is flammable burns easily","cn":"易燃的"}]},"vocab":{"pos":"adj","senses":[{"en":"Don't smoke when you're getting gas at the gas station! Gasoline is flammable , as is dry grass, old wood, cloth and mattresses."}]},"collocations":{"phrases":["VERBS be","ADV. highly These materials are highly flammable."]},"media":{"uk":"media/ldoce/hwd/bre/e/flammable0205.mp3","us":"media/ldoce/hwd/ame/9/flammable.mp3"},"examples":[{"en":"highly flammable liquids","cn":"高度易燃的液体"},{"en":"Caution! Highly flammable liquid.","cn":"小心！高度易燃液体。"}]},"flask":{"collins":{"senses":[{"pos":"N-COUNT","cn":"(可随身携带饮料的)瓶子","en":"A flask is a bottle which you use for carrying drinks around with you. 【搭配模式】：N of n He took out a metal from a canvas bag. 他从帆布包里拿出一个金属瓶子。 A flask of liquid is the flask and the liquid which it contains. There's some sandwiches here and a "},{"pos":"N-COUNT","cn":"烧瓶;长颈瓶","en":"; ; A flask is a bottle or other container which is used in science laboratories and industry for holding liquids. ... s for the transport of spent fuel. 用来运送废弃燃料的瓶子"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a special type of bottle that you use to keep liquids either hot or cold, for example when travelling","cn":"保温瓶，保温杯"},{"en":"a hip flask","cn":"扁酒瓶"},{"en":"a glass bottle with a narrow top, used in a laboratory 〔","cn":"实验室用的〕烧瓶"}]},"collocations":{"phrases":["ADJ. Thermos(R), vacuum | hip | metal, silver | conical, culture, round bottom (all science)","VERB + FLASK fill | carry When he climbed in the snow he always carried a silver flask of brandy for emergencies. | pull out She pulled out ","FLASK + VERB contain sth a culture flask containing 4ml of the medium","PREP. ~ of We took a flask of tea with us."]},"media":{"img":["media/ldoce/img/thermos.jpg"],"uk":"media/ldoce/hwd/bre/2/flask0205.mp3","us":"media/ldoce/hwd/ame/6/flask.mp3"},"examples":[{"en":"a flask of tea/coffee","cn":"一保温瓶的茶/咖啡"}]},"flog":{"collins":{"senses":[{"pos":"VERB","cn":"出售;卖掉","en":"If someone tries to flog something, they try to sell it. 【语法信息】：V n 【语域标签】：BRIT 英 【STYLE标签】：INFORMAL 非正式 They are trying to their house. 他们正试图卖掉房子。"},{"pos":"VERB","cn":"鞭笞;棒打","en":"If someone is flogged , they are hit very hard with a whip or stick as a punishment. 【语法信息】： be V-ed 【语法信息】：V n In these places people starved, were ged, were clubbed to death... 在这些地方，人们忍饥挨饿，遭受鞭打，甚至会被乱棍打死。 Flog them soundly. 好好鞭打他们一顿。"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to give something to someone in exchange for money","cn":""},{"en":"to send goods to another country to be sold","cn":""},{"en":"to buy and sell a particular type of goods as part of your business","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To flog is to beat or hit, especially with a tool like a stick or rod. A cruel trainer might flog an unruly horse with a whip."}]},"collocations":{"phrases":["ADV. publicly Offenders were publicly flogged.","PHRASES flog sb to death"]},"media":{"uk":"media/ldoce/hwd/bre/2/flog0205.mp3","us":"media/ldoce/hwd/ame/f/flog.mp3"},"examples":[{"en":"He was publicly flogged for breaking the country's alcohol laws.","cn":"他因违犯国家的酒法而被当众处以鞭刑。"},{"en":"I had a letter from a company trying to flog me insurance.","cn":"我收到了一家公司的信，向我推销保险。"}]},"flinch":{"collins":{"senses":[{"pos":"VERB","cn":"退缩;畏缩","en":"If you flinch , you make a small sudden movement, especially when something surprises you or hurts you. 【语法信息】：V 【搭配模式】：usu neg Murat had looked into the eyes of the firing squad without ing... 穆拉特毫不退缩地直视着执行枪决的行刑队员们的眼睛。 The sharp surface of"},{"pos":"VERB","cn":"躲避;回避;不愿意做","en":"If you flinch from something unpleasant, you are unwilling to do it or think about it, or you avoid doing it. 【语法信息】：V 【语法信息】：V from n The world community should not in the face of this challenge... 国际社会在面对这一挑战时不应该回避。 He has never ed from h"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to move your face or body away from someone or something because you are in pain, frightened, or upset 〔","cn":"因疼痛﹑害怕﹑生气而〕退缩﹐畏缩"},{"en":"to feel embarrassed or upset","cn":"尴尬﹔生气"},{"en":"to be willing to do something even though it is difficult or unpleasant","cn":"不回避（做）某事"}]},"vocab":{"pos":"v n","senses":[{"en":"To flinch is to react to pain by wincing, pulling away, or cringing. Often it's used to describe a person who shows a moment of weakness or fright: he was so tough, I thought he'd never flinch , but snakes really freak him out."}]},"collocations":{"phrases":["ADV. violently | almost | hardly He hardly flinched when he was hit. | slightly | visibly | inwardly She flinched inwardly as he took her ha","VERB + FLINCH make sb Her finger touched the scar on his forehead, making him flinch.","PREP. at She flinched visibly at the sight of the body. | from She flinched away from him. (figurative) She won't flinch from speaking her m"]},"media":{"uk":"media/ldoce/hwd/bre/c/flinch0205.mp3","us":"media/ldoce/hwd/ame/4/flinch.mp3"},"examples":[{"en":"He never flinched from facing up to trouble.","cn":"他敢于面对困难，从不退缩。"},{"en":"He met my gaze without flinching.","cn":"他毫不畏缩，跟我对视着。"}]},"fling":{"collins":{"senses":[{"pos":"VERB","cn":"猛掷;用力抛","en":"If you fling something somewhere, you throw it there using a lot of force. 【语法信息】：V n prep/adv The woman flung the cup at him... 那个女人使劲把杯子朝他扔去。 He once seized my knitting, ing it across the room. 有一次他抓过我织的东西，把它扔到了屋子的另一头。"},{"pos":"VERB","cn":"突然冲向;突然跳向","en":"If you fling yourself somewhere, you move or jump there suddenly and with a lot of force. 【语法信息】：V pron-refl prep/adv He flung himself to the floor. 他突然跳到地板上。"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make something such as a ball or stone move quickly through the air using your hand","cn":""},{"en":"to throw something, especially in a careless way without using much effort","cn":""},{"en":"to throw something with a lot of force","cn":""}]},"vocab":{"pos":"1 v n 2 v n 3 n","senses":[{"en":"To fling is to throw something with force. You'll start a food fight in the cafeteria if you fling your vegetables at the kid across the table."}]},"collocations":{"phrases":["ADJ. brief | (one) final, (one) last The athlete will have one final fling (= participate in one final competition) before retirement.","VERB + FLING have She's had her fling and now she's got to settle down.","PREP. ~ with He had a fling with his neighbour's wife."]},"media":{"uk":"media/ldoce/hwd/bre/7/fling_v0205.mp3","us":"media/ldoce/hwd/ame/d/fling1.mp3"},"examples":[{"en":"He was determined to have one last fling before retiring.","cn":"他决心在退休前最后来一次痛痛快快的玩乐。"},{"en":"He flung out an arm to stop her from falling.","cn":"他猛伸手臂扶她，她才没有跌倒。"}]},"flea":{"collins":{"senses":[{"pos":"N-COUNT","cn":"蚤;跳蚤","en":"A flea is a very small jumping insect that has no wings and feeds on the blood of humans or animals."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a very small insect without wings that jumps and bites animals and people to eat their blood","cn":"跳蚤"},{"en":"to talk angrily to someone, especially because they have done something you disapprove of 〔","cn":"尤指因某人做了你不赞成的事而〕一顿臭骂轰走某人"}]},"collocations":{"phrases":["ADJ. cat, dog, etc.","VERB + FLEA get, have | be riddled with | control This drug is given to dogs to control fleas.","FLEA + VERB jump | bite | carry/spread disease","FLEA + NOUN bite | collar, powder"]},"media":{"uk":"media/ldoce/hwd/bre/2/brelasdeflea.mp3","us":"media/ldoce/hwd/ame/4/flea.mp3","img":["media/thumb/flea.jpg"]},"examples":[{"en":"The dog has fleas.","cn":"这条狗有跳蚤。"},{"en":"Are you sure the dog has fleas ?","cn":"你确定那只狗身上有跳蚤吗？"}]},"fluctuate":{"collins":{"senses":[{"pos":"VERB","cn":"变动;波动;上下浮动","en":"If something fluctuates , it changes a lot in an irregular way. 【语法信息】：V 【语法信息】：V-ing Body temperature can if you are ill. 人患病后体温可能会上下波动。 ...the fluctuating price of oil. 油价的浮动"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to change often","cn":""},{"en":"if something varies , it changes according to what the situation is","cn":""},{"en":"if something such as a price or amount fluctuates , it changes very often from a high level to a low one and back again","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"Something that fluctuates varies or changes — it's the opposite of steady. Like the ups and downs of the stock market or the relationship status of a Hollywood starlet."}]},"collocations":{"phrases":["ADV. considerably | sharply, widely, wildly Prices have fluctuated wildly in recent years. | constantly, continually constantly fluctuating ","PREP. according to Traffic congestion fluctuates according to the time of day. | around The number of boys at the school fluctuates around 1"]},"media":{"uk":"media/ldoce/hwd/bre/1/fluctuate0205.mp3","us":"media/ldoce/hwd/ame/a/fluctuate.mp3"},"examples":[{"en":"During the crisis, oil prices fluctuated between $20 and $40 a barrel.","cn":"在危机时期，每桶石油价格在 20 元至 40 元之间波动。"},{"en":"Temperatures can fluctuate by as much as 10 degrees.","cn":"温差可达 10 度之多。"}]},"flannel":{"collins":{"senses":[{"pos":"N-UNCOUNT","cn":"法兰绒","en":"Flannel is a soft cloth, usually made of cotton or wool, that is used for making clothes. 【搭配模式】：oft N n He wore a faded red shirt. 他身穿一件褪了色的红色法兰绒衬衫。"},{"pos":"N-PLURAL","cn":"法兰绒男裤","en":"Flannels are men's trousers made of flannel. 【搭配模式】：also a pair of N 【STYLE标签】：OLD-FASHIONED 过时 ...respectable young chaps, dressed in s and blazers. 穿着法兰绒裤子和夹克的体面小伙子们"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"soft cloth, usually made of cotton or wool, used for making clothes 〔","cn":"用作衣料的〕法兰绒"},{"en":"a piece of cloth you use to wash yourself 〔","cn":"洗澡用的〕毛巾"},{"en":"something that someone says that has no real meaning or does not tell you what you want to know","cn":"废话﹔兜圈子的话"}]},"collocations":{"phrases":["ADJ. damp, wet | cold | face","VERB + FLANNEL use Use a damp flannel to clean the skin.","PREP. with a ~ She wiped his eyes and nose with a wet face flannel."]},"media":{"uk":"media/ldoce/hwd/bre/c/flannel_n0205.mp3","us":"media/ldoce/hwd/ame/0/flannel.mp3"},"examples":[{"en":"a grey flannel suit","cn":"一套灰法兰绒西服"},{"en":"a flannel shirt","cn":"法兰绒衬衣"}]},"flushed":{"collins":{"senses":[{"pos":"ADJ-GRADED","cn":"兴奋的;激动的","en":"If you say that someone is flushed with success or pride you mean that they are very excited by their success or pride. 【搭配模式】：v-link ADJ with n Grace was with the success of the venture... 格雷斯为冒险成功而感到兴奋。 The publishers were with triumph wh"}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"red in the face","cn":"脸红的"},{"en":"excited because you have achieved something","cn":"因成功/激动/满意等而兴奋的"}]},"vocab":{"pos":"adj","senses":[{"en":"When you're flushed , your cheeks are pink. You probably look flushed after your morning jog around the block."}]},"collocations":{"phrases":["VERBS appear, be, feel, look | become","ADV. deeply, extremely, very | a bit, faintly, a little, quite, slightly | unnaturally","PREP. with Her face was flushed with embarrassment."]},"media":{"uk":"media/ldoce/hwd/bre/a/brelasdeflushed.mp3","us":"media/ldoce/hwd/ame/4/flushed.mp3"},"examples":[{"en":"( figurative ) He was flushed with success (= very excited and pleased) after his first novel was published.","cn":"他的第一部小说发表以后，他志得意满。"},{"en":"Her face was flushed with anger.","cn":"她的脸气红了。"}]},"flurry":{"collins":{"senses":[{"pos":"N-COUNT","cn":"(活动或兴奋心情的)一阵","en":"A flurry of something such as activity or excitement is a short intense period of it. 【搭配模式】：usu N of n ...a of diplomatic activity aimed at ending the war. 旨在结束战争的一系列外交活动"},{"pos":"N-COUNT","cn":"(雪等的)一阵","en":"A flurry of something such as snow is a small amount of it that suddenly appears for a short time and moves in a quick, swirling way. 【搭配模式】：oft N of n"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a time when there is suddenly a lot of activity and people are very busy","cn":"一阵忙乱"},{"en":"a small amount of snow or rain that is blown by the wind 〔","cn":"雪或雨的〕微飘﹐一阵"}]},"vocab":{"pos":"n v","senses":[{"en":"A light blowing swirl of snow that's just barely falling is a flurry . There might be a brief flurry or two at the beginning of the winter, with no real heavy snow until January."}]},"collocations":{"phrases":["ADJ. snow","PHRASES a flurry of rain/snow 2 short sudden burst of sth","ADJ. brief, sudden There was a sudden flurry of interest in the book.","PREP. ~ of","PHRASES a flurry of activity/excitement"]},"media":{"uk":"media/ldoce/hwd/bre/f/flurry0205.mp3","us":"media/ldoce/hwd/ame/9/flurry1.mp3"},"examples":[{"en":"The ladies departed in a flurry of silks and satins.","cn":"女士们在一片绸缎窸窣声中离去。"},{"en":"Her arrival caused a flurry of excitement.","cn":"她的到来引起了一阵哄动。"}]},"flap":{"collins":{"senses":[{"pos":"V-ERG","cn":"(使)飘动;摆动;抖搂","en":"If something such as a piece of cloth or paper flaps or if you flap it, it moves quickly up and down or from side to side. 【语法信息】：V 【语法信息】：V n Grey sheets ped on the clothes line... 灰色的床单在晾衣绳上飘来摆去的。 They would bath towels from their balconi"},{"pos":"V-ERG","cn":"振(翅);挥(翅);(翅膀)拍打，抖动","en":"If a bird or insect flaps its wings or if its wings flap , the wings move quickly up and down. 【语法信息】：V pl-n 【语法信息】：V The bird ped its wings furiously... 鸟儿使劲地扑打着翅膀。 A pigeon emerges, wings ping noisily, from the tower. 一只鸽子从塔里钻出来，扑扑地拍打着翅膀。"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a thin flat piece of cloth, paper, skin etc that is fixed by one edge to a surface, which you can lift up easily 〔","cn":"布﹑纸﹑皮等做的〕片状垂悬物"},{"en":"the noisy movement of something such as cloth in the air 〔","cn":"布等在空中的〕拍打﹐拍动"},{"en":"a situation in which people feel very excited or worried about something","cn":"激动﹔慌乱﹐焦急"}]},"vocab":{"pos":"1 v n 2 n v 3 v","senses":[{"en":"You're probably familiar with the verb to \"flap,\" which is what birds do with their wings. But as a noun, a flap is a fuss, an argument, or a gossipy feud."}]},"collocations":{"phrases":["ADV. gently | wildly The sails flapped wildly in the stiff breeze. | about, around"]},"media":{"uk":"media/ldoce/hwd/bre/2/flap_las3_br.mp3","us":"media/ldoce/hwd/ame/6/flap1.mp3"},"examples":[{"en":"She walked up and down, flapping her arms to keep warm.","cn":"她来回走动，挥动着双臂使身体暖和起来。"},{"en":"There's no need to flap — I've got everything under control.","cn":"不必担心，一切都已在我控制之中。"}]},"float":{"collins":{"senses":[{"pos":"V-ERG","cn":"(使)漂浮;(使)浮动","en":"If something or someone is floating in a liquid, they are in the liquid, on or just below the surface, and are being supported by it. You can also float something on a liquid. 【语法信息】：V in n 【语法信息】：V prep/adv 【语法信息】：V n 【语法信息】：Also V n prep/"},{"pos":"VERB","cn":"漂;浮","en":"Something that floats lies on or just below the surface of a liquid when it is put in it and does not sink. 【语法信息】：V Empty things . 空的物体会在水中浮起。"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to be supported on the surface of water by the water itself","cn":""},{"en":"to stay on the surface of water without sinking","cn":""},{"en":"to formally suggest that something should be done, especially at a meeting","cn":""}]},"vocab":{"pos":"1 v n 2 n v 3 v 4 v ","senses":[{"en":"Float is what you do when you're lying on the water. Hopefully you know how to swim, so you can float suspended on the surface of the water, rather than sinking straight to the bottom."}]},"collocations":{"phrases":["ADV. gently | downstream, downwards | upwards In the dream my feet leave the ground and I start to float upwards. | about, around, away, off","VERB + FLOAT seem to Her voice seemed to float on the water as gently as a slight mist.","PREP. across A few small clouds floated across the sky. | down chunks of ice floating down the river | in pieces of wood floating in the wat","ADV. freely The government decided to allow the peso to float freely.","VERB + FLOAT allow sth to"]},"media":{"img":["media/ldoce/img/float.jpg"],"uk":"media/ldoce/hwd/bre/c/brelasdefloat.mp3","us":"media/ldoce/hwd/ame/e/float1.mp3"},"examples":[{"en":"Shares were floated at 585p.","cn":"股票最初上市价为 5 英镑 85 便士。"},{"en":"( figurative ) People seem to float in and out of my life.","cn":"不同的人在我的生命中出现和消失。"}]},"fluid":{"collins":{"senses":[{"pos":"N-MASS","cn":"液体;流质","en":"A fluid is a liquid. 【语域标签】：FORMAL 正式 The blood vessels may leak , which distorts vision... 血管可能会渗漏，造成视力模糊。 Make sure that you drink plenty of s. 务必保证足够的水分摄入。 ... retention. 体液潴留"},{"pos":"ADJ-GRADED","cn":"(动作、线条或设计)流畅优美的，优雅自然的","en":"Fluid movements or lines or designs are smooth and graceful. The forehand stroke should be and well balanced. 正手击球应该保证动作流畅和平稳。 ...long, dresses. 线条优雅流畅的长裙"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a substance, such as water or milk, that is not a solid and not a gas","cn":""},{"en":"a liquid - used especially in technical contexts","cn":""},{"en":"a liquid","cn":"流体﹐液（体）"}]},"vocab":{"pos":"1 n adj 2 adj 3 adj","senses":[{"en":"Something that is unstable or subject to change can be described as fluid . The fluid political situation in a particular country makes it unsafe to travel there, with the constant possibility of a violent uprising."}]},"collocations":{"phrases":["ADJ. excess | amniotic, bodily/body, intravenous | brake, cleaning","VERB + FLUID drink Change your diet and drink plenty of fluids. | lose | replace replacing vital body fluids and salts that are lost when yo"]},"media":{"uk":"media/ldoce/hwd/bre/b/brelasdefluid.mp3","us":"media/ldoce/hwd/ame/a/l3fluid.mp3"},"examples":[{"en":"a loose, fluid style of dancing","cn":"灵活流畅优美的跳舞风格"},{"en":"The doctor told him to drink plenty of fluids.","cn":"医生要他多喝流质。"}]},"flutter":{"collins":{"senses":[{"pos":"V-ERG","cn":"颤动;飘动;挥动","en":"If something thin or light flutters , or if you flutter it, it moves up and down or from side to side with a lot of quick, light movements. 【语法信息】：V 【语法信息】：V n 【语法信息】：V-ing Her chiffon skirt was ing in the night breeze. 她的雪纺裙在晚风中飘动着。 ...a b"},{"pos":"VERB","cn":"(小鸟)振翅飞翔;(纸片)飘飞，翩翩飞舞","en":"If something light such as a small bird or a piece of paper flutters somewhere, it moves through the air with small quick movements. 【语法信息】：V adv/prep 【语法信息】：V The paper ed to the floor... 纸飘落到地板上。 The birds were active, whirring and ing am"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if a bird or insect flutters, or if it flutters its wings, it flies by moving its wings lightly up and down","cn":"振（翼）﹐拍打（翅膀）"},{"en":"to make small gentle movements in the air 〔","cn":"在空中〕飘扬﹐飘动"},{"en":"if your heart or your stomach flutters, you feel very excited or nervous 〔","cn":"心脏或胃因激动或紧张而〕悸动﹐颤抖"}]},"vocab":{"pos":"1 v n 2 n","senses":[{"en":"Flutter means to move back and forth rapidly. Flags flutter in the wind. Leaves flutter to the ground. Flutter also exists as a noun—you might feel a flutter in your heart when you're excited."}]},"collocations":{"phrases":["ADJ. little","VERB + FLUTTER give His heart gave a little flutter as the ladder slipped a couple of inches. 2 state of nervous excitement","VERB + FLUTTER be in, feel She felt a flutter of excitement. | get in | cause","PREP. in a ~ They arrived in a flutter. | ~ of"]},"media":{"uk":"media/ldoce/hwd/bre/d/flutter_v0205.mp3","us":"media/ldoce/hwd/ame/1/flutter1.mp3"},"examples":[{"en":"( figurative ) The sound of his voice in the hall made her heart flutter.","cn":"他在大厅中讲话的声音使她的心怦怦直跳。"},{"en":"Her eyelids fluttered but did not open.","cn":"她的眼皮动了一下，但没有睁开眼。"}]}});
